import{_ as n,o as s,c as r,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/berufskolleg/gruppenprozesse-bk-teilleistungen.png",c=JSON.parse('{"title":"BK-Prüfungsnoten aus Teilleistungen übernehmen","description":"","frontmatter":{"title":"BK-Prüfungsnoten aus Teilleistungen übernehmen","source_pageid":1281,"source_revision":4703},"headers":[],"relativePath":"zeugnisse/berufskolleg/kurse-algorithmisch-markieren-gruppenprozesse-bk-abschluss.md","filePath":"zeugnisse/berufskolleg/kurse-algorithmisch-markieren-gruppenprozesse-bk-abschluss.md"}'),l={name:"zeugnisse/berufskolleg/kurse-algorithmisch-markieren-gruppenprozesse-bk-abschluss.md"};function u(o,e,a,g,h,p){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="bk-prufungsnoten-aus-teilleistungen-ubernehmen" tabindex="-1">BK-Prüfungsnoten aus Teilleistungen übernehmen <a class="header-anchor" href="#bk-prufungsnoten-aus-teilleistungen-ubernehmen" aria-label="Permalink to &quot;BK-Prüfungsnoten aus Teilleistungen übernehmen&quot;">​</a></h1><p>Übernehmen Sie Vor-, Prüfungs- oder Abschlussnoten aus den vorbereiteten Teilleistungen in den Bereich BK-Abschluss. Wählen Sie die passende Notenart und beachten Sie die Überschreiboption.</p><p><a href="/bilder/berufskolleg/gruppenprozesse-bk-teilleistungen.png"><img src="'+t+'" alt="Übertragen Sie Teilleistungen in den Reiter Schüler ➜ BK-Abschluss." loading="lazy"></a></p><p><em>Übertragen Sie Teilleistungen in den Reiter Schüler ➜ BK-Abschluss.</em></p><p>Über den Gruppenprozess <strong>Prüfungsnoten aus Teilleistungen holen</strong> können generell Teilleistungen in den Reiter <em>Schüler ➜ BK-Abschluss</em> übernommen werden.</p><p>Der Prozess übernimmt <strong>mündliche und schriftliche Prüfungsnoten</strong> sowie <strong>Vornoten</strong>. Unterscheiden Sie bei den Vornoten: Die Leistungsdaten des aktuellen Abschnitts enthalten Halbjahresnoten. Nach der jeweiligen Prüfungsordnung kann für die Vornote jedoch die Leistung des ganzen Schuljahres maßgeblich sein.</p><p>Weiterhin lassen sich <em>allgemeinbildende</em> und <em>berufsbezogene Abschlussnoten</em> aus ihren Teilleistungen mit diesem Gruppenprozess holen.</p><p>Im Gruppenprozess ist die <strong>Notenart</strong> zu wählen, diese Einträge entsprechen den Spalten im Reiter <em>BK-Abschluss</em>. Je nach ausgewählter Schülergruppe stehen nicht alle Teilleistungsarten zur Verfügung.</p><p>Die <strong>Zugehörige Teilleistung</strong> enthält die in SchILD-NRW definierten Teilleistungen. Wählen Sie hier die, in der die passende Note hinterlegt wurde.</p><p>Über den Schalter <strong>Vorhandene Noten überschreiben</strong> lässt sich einstellen, ob vorhandene Noten behalten oder neu aus den Teilleistungen gesetzt werden.</p><p>Klicken Sie dann auf <code>Noten holen</code>, um den Prozess zu beginnen. Über <em>Abbrechen</em> wird der Prozess beendet, ohne dass eine Änderung an den Daten durchgeführt wird.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kurse_algorithmisch_markieren_(Gruppenprozesse_BK-Abschluss)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4703.</p>',13)])])}const b=n(l,[["render",u]]);export{c as __pageData,b as default};
